def _now() -> str:
    return datetime.now().isoformat(timespec="seconds")


def _safe_component(value: str, fallback: str = "item") -> str:
    cleaned = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', "_", str(value or "")).strip(" .")
    return cleaned[:100] or fallback


def _atomic_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(text, encoding="utf-8")
    os.replace(temporary, path)


def _atomic_json(path: Path, value: Any) -> None:
    _atomic_text(path, json.dumps(value, ensure_ascii=False, indent=2) + "\n")


def _atomic_bytes_verified(path: Path, data: bytes) -> str:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_bytes(data)
    digest = hashlib.sha256(data).hexdigest()
    if _sha256_file(temporary) != digest:
        temporary.unlink(missing_ok=True)
        raise RuntimeError(f"Derived file write verification failed: {path}")
    os.replace(temporary, path)
    if not path.is_file() or _sha256_file(path) != digest:
        raise RuntimeError(f"Derived file readback verification failed: {path}")
    return digest


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        while True:
            chunk = source.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def _copy_static_permanent_authoring_contracts(
    materials_dir: Path,
) -> dict[str, Path]:
    sources = {
        GLOBAL_CHATGPT_WRITING_RULES_FILENAME: GLOBAL_CHATGPT_WRITING_PROMPT_PATH,
        LATEX_IMPORT_CONTRACT_FILENAME: LATEX_IMPORT_CONTRACT_PATH,
        LATEX_DRAWING_RULES_FILENAME: LATEX_DRAWING_RULES_PATH,
        REFERENCE_AND_CONTINUITY_PROMPT_FILENAME: (
            REFERENCE_AND_CONTINUITY_PROMPT_PATH
        ),
    }
    copied: dict[str, Path] = {}
    for filename, source in sources.items():
        if not source.is_file() or not source.read_text(encoding="utf-8").strip():
            raise FileNotFoundError(
                f"Permanent online-course authoring contract is missing: {source}"
            )
        target = materials_dir / filename
        _copy_file_verified(source, target)
        copied[filename] = target
    return copied


def _load_curated_diagram_materials(
    materials_dir: Path,
) -> tuple[list[DiagramObligation], list[Path]]:
    filenames = (
        DIAGRAM_OBLIGATIONS_FILENAME,
        DIAGRAM_SPECIFICATIONS_FILENAME,
        LATEX_DIAGRAMS_FILENAME,
    )
    paths = [materials_dir / filename for filename in filenames]
    existing = [path for path in paths if path.is_file()]
    if not existing:
        return [], []
    if len(existing) != len(paths):
        missing = [path.name for path in paths if not path.is_file()]
        raise RuntimeError(
            "Curated diagram materials are incomplete; missing: "
            + ", ".join(missing)
        )
    try:
        payload = json.loads(paths[0].read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        raise RuntimeError("DIAGRAM_OBLIGATIONS.json is invalid.") from error
    rows = payload.get("obligations") if isinstance(payload, dict) else None
    if not isinstance(rows, list) or not rows:
        raise RuntimeError("DIAGRAM_OBLIGATIONS.json has no obligations.")
    obligations = [DiagramObligation.model_validate(row) for row in rows]
    obligation_ids = {item.obligation_id for item in obligations}
    specs = paths[1].read_text(encoding="utf-8")
    latex = paths[2].read_text(encoding="utf-8")
    # Historical curated files sometimes contained raw tikzpicture bodies.
    # The formal authoring surface now has one representation only, so curated
    # figures must obey the same backend=tikz source-block protocol.
    validate_online_course_diagram_protocol(latex)
    missing_specs = sorted(
        obligation_id
        for obligation_id in obligation_ids
        if obligation_id not in specs
    )
    latex_ids = set(
        re.findall(
            r"(?mi)^\s*%\s*MPB-DIAGRAM:\s*(diagram-[a-f0-9]{16})\s+realized\s*$",
            latex,
        )
    )
    missing_latex = sorted(obligation_ids - latex_ids)
    unknown_latex = sorted(latex_ids - obligation_ids)
    if missing_specs or missing_latex or unknown_latex:
        raise RuntimeError(
            "Curated diagram materials disagree: "
            f"missing specs={missing_specs}, missing LaTeX={missing_latex}, "
            f"unknown LaTeX={unknown_latex}."
        )
    return obligations, paths


def _restore_curated_diagram_materials_from_zip(
    package_path: Path,
    materials_dir: Path,
) -> None:
    filenames = (
        DIAGRAM_OBLIGATIONS_FILENAME,
        DIAGRAM_SPECIFICATIONS_FILENAME,
        LATEX_DIAGRAMS_FILENAME,
    )
    if any((materials_dir / filename).is_file() for filename in filenames):
        return
    if not package_path.is_file():
        return
    try:
        with zipfile.ZipFile(package_path, "r") as archive:
            available = [filename in archive.namelist() for filename in filenames]
            if not any(available):
                return
            if not all(available):
                raise RuntimeError(
                    "Existing subsection ZIP contains an incomplete curated diagram set."
                )
            for filename in filenames:
                _atomic_bytes_verified(
                    materials_dir / filename,
                    archive.read(filename),
                )
    except (OSError, zipfile.BadZipFile, KeyError) as error:
        raise RuntimeError(
            "Existing subsection ZIP diagram materials cannot be restored."
        ) from error


def _whole_subsection_writing_prompt(
    *,
    unit_kind: str,
    number: str,
    title: str,
    source_segment_count: int,
) -> str:
    """Return the permanent whole-writing-unit contract stored in every package."""
    unit = "section" if str(unit_kind) == "section" else "subsection"
    segment_description = (
        f"The archive contains {int(source_segment_count)} physical recording segments."
        if int(source_segment_count) > 0
        else "The archive currently contains no physical recording segment."
    )
    return f"""PERMANENT WHOLE-{unit.upper()} WRITING CONTRACT

Read this entire file before planning or drafting. It is the mandatory
output-granularity companion to `GLOBAL_CHATGPT_WRITING_RULES.txt`.

Target: {unit} {number} `{title}`.

{segment_description} Physical recording segments, platform parts, timestamps,
recording sessions, imported fragments, and evidence blocks are evidence boundaries
only. They are never writing-unit boundaries and must never determine the structure
of the returned lecture notes.

MANDATORY SINGLE-RESPONSE RULE:
- In one response, write the complete LaTeX body for the entire target {unit}, from
  its mathematical beginning through its mathematical end.
- Integrate all in-scope segments before writing. Organize the result by mathematical
  logic, dependency, and exposition, not by segment order or recording chronology.
- Do not return one segment at a time. Do not produce Part 1 / Part 2, recording-
  segment labels, repeated introductions, repeated conclusions, or separate drafts.
- Do not stop after an early segment, ask for the next segment, or promise to continue
  in another response.
- Deduplicate deliberate recording overlap while preserving every distinct supported
  definition, hypothesis, formula, theorem, proof, example, exercise, and explanation
  assigned to this {unit}.
- Content outside this exact formal {unit} remains out of scope.

MANDATORY WHOLE-UNIT PLANNING RULE:

Before drafting, privately plan the entire target as one teaching unit. Identify:

- core definitions;
- main structural results;
- previously established prerequisites;
- current proof obligations;
- examples and calculations;
- optional technical or advanced supplements;
- later-unit material that must not be developed here.

Reconcile that plan with the private CONTINUITY COLLISION LEDGER required by
`GLOBAL_CHATGPT_WRITING_RULES.txt`. Assign each substantial mathematical item one
principal ownership location before deciding how much to state or prove here. Do
not print the plan or ledger.

CORE-NARRATIVE RULE:

- Make the first-reading conceptual line visible before long optional supplements.
- State a core definition or theorem before its long technical supplement whenever
  mathematically legitimate.
- Mark an advanced supplement with brief first-reading guidance and resume the main
  conceptual line immediately afterward.
- State the exact version of any necessary external prerequisite, but do not prove
  it unless its proof is assigned to this target.
- A closing transition may preview the next unit briefly, but must not develop that
  unit's formal theory here.

This contract is permanent and non-negotiable. If another instruction treats a
physical recording segment as a separate output unit, this whole-{unit}, one-response
contract takes precedence for this material package.
"""


